using MedClinic.Application.Interfaces;
using MedClinic.Domain.Entities;
using MedClinic.Domain.Enums;
using MedClinic.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
namespace MedClinic.Infrastructure.Services;
public sealed class ConsentService : IConsentService { readonly ApplicationDbContext _db; readonly ITenantContext _tenant; public ConsentService(ApplicationDbContext db, ITenantContext tenant){_db=db;_tenant=tenant;} public async Task<ConsentDto> RecordAsync(Guid patientId,ConsentType type,bool granted,DateTime? expiresAt,string? notes,Guid? witnessUserId,string? ipAddress,CancellationToken ct=default){var p=await _db.Patients.FirstOrDefaultAsync(x=>x.Id==patientId&&x.ClinicId==_tenant.ClinicId,ct)??throw new KeyNotFoundException("Patient not found.");if(expiresAt is not null&&expiresAt<=DateTime.UtcNow)throw new ArgumentException("Consent expiry must be in the future.");var c=new ConsentRecord{Id=Guid.NewGuid(),ClinicId=p.ClinicId,PatientId=patientId,ConsentType=type,IsGranted=granted,GrantedAt=DateTime.UtcNow,ExpiresAt=expiresAt,WitnessUserId=witnessUserId,IpAddress=ipAddress,Notes=notes?.Trim(),CreatedAt=DateTime.UtcNow};_db.ConsentRecords.Add(c);await _db.SaveChangesAsync(ct);return Map(c);} public async Task<ConsentDto> RevokeAsync(Guid patientId,Guid consentId,string reason,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Revocation reason is required.");var c=await _db.ConsentRecords.FirstOrDefaultAsync(x=>x.Id==consentId&&x.PatientId==patientId&&x.ClinicId==_tenant.ClinicId,ct)??throw new KeyNotFoundException("Consent record not found.");c.IsGranted=false;c.ExpiresAt=DateTime.UtcNow;c.Notes=$"Revoked: {reason.Trim()}";c.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync(ct);return Map(c);} public async Task<IReadOnlyList<ConsentDto>> GetHistoryAsync(Guid patientId,CancellationToken ct=default)=>await _db.ConsentRecords.Where(x=>x.PatientId==patientId&&x.ClinicId==_tenant.ClinicId).OrderByDescending(x=>x.GrantedAt).Select(x=>new ConsentDto(x.Id,x.PatientId,x.ConsentType,x.IsGranted,x.GrantedAt,x.ExpiresAt,x.WitnessUserId,x.Notes,x.IsGranted&&(x.ExpiresAt==null||x.ExpiresAt>DateTime.UtcNow))).ToListAsync(ct); public Task<bool> HasActiveConsentAsync(Guid patientId,ConsentType type,CancellationToken ct=default)=>_db.ConsentRecords.AnyAsync(x=>x.PatientId==patientId&&x.ClinicId==_tenant.ClinicId&&x.ConsentType==type&&x.IsGranted&&(x.ExpiresAt==null||x.ExpiresAt>DateTime.UtcNow),ct); static ConsentDto Map(ConsentRecord x)=>new(x.Id,x.PatientId,x.ConsentType,x.IsGranted,x.GrantedAt,x.ExpiresAt,x.WitnessUserId,x.Notes,x.IsGranted&&(x.ExpiresAt==null||x.ExpiresAt>DateTime.UtcNow)); }